_LOCAL_VERIFY_WRAPPER = """#!/usr/bin/env bash
# Conversion wrapper: run the checker and normalize its outcome into the
# score file. A non-zero checker status, or a score the checker failed to
# emit in a parseable form, maps to 0.0; the wrapper itself always exits 0
# so the outer loop treats the episode as scored.
cd "$(dirname "$0")/.."
mkdir -p verify
bash reward/reward.sh > verify/reward.raw 2> verify/checker.err
rc=$?
score=$(python3 - <<'PYEOF'
import json, os, re
raw = ""
if os.path.exists("verify/reward.raw"):
    raw = open("verify/reward.raw", encoding="utf-8", errors="replace").read()
score = None
try:
    obj = json.loads(raw)
    if isinstance(obj, dict):
        vals = [v for v in obj.values() if isinstance(v, (int, float)) and not isinstance(v, bool)]
        if vals:
            score = sum(vals) / len(vals)
except Exception:
    pass
if score is None:
    for line in reversed(raw.splitlines()):
        s = line.strip()
        if re.fullmatch(r"[-+]?(\\d+(\\.\\d*)?|\\.\\d+)([eE][-+]?\\d+)?", s):
            score = float(s)
            break
print("" if score is None else format(score, ".12g"))
PYEOF
)
if [ "$rc" -ne 0 ] || [ -z "$score" ]; then
    printf '0.0\\n' > reward.txt
else
    printf '%s\\n' "$score" > reward.txt
fi
exit 0
"""

_LOCAL_CHECKER = """#!/usr/bin/env bash
# Original checker: run the task's grading script over the final workspace
# and print the raw score payload. Non-zero exit marks the episode unsolved.
cd "$(dirname "$0")/.."
exec python3 reward/test.py "$(pwd)"
"""


def _normalize_hidden_tests(hidden) -> dict[str, str]:
    """Accept both shapes the dataset rows carry: a single pytest file's
    source (path fixed at tests/test_hidden.py) or a {path: source} mapping
    of withheld checker files (the reward/ tree)."""
    if not hidden:
        return {}
    if isinstance(hidden, str):
        return {"tests/test_hidden.py": hidden}
    return {str(k): str(v) for k, v in hidden.items()}


async def run_local_evaluation(
    md: dict,
    sb: Sandbox,
    *,
    diff_text: str,
    ep_dir: str | None,
    timeout_sec: int,
) -> EvalResult:
    """Grade the episode inside its own sandbox instance.

    Uploads the withheld checker files plus the verify chain into the
    instance, runs the conversion wrapper, and reads back reward.txt. Any
    verify-side failure is folded into a legal 0.0 score — the episode still
    counts as scored so training can proceed; diagnostics land in the
    per-episode archive only.
    """
    workdir = md["workdir"]
    grading = md.get("grading") or {}
    try:
        for path, content in _normalize_hidden_tests(grading.get("hidden_tests")).items():
            await sb.write_file(f"{workdir}/{path}", content, user="agent")
        await sb.write_file(f"{workdir}/reward/reward.sh", _LOCAL_CHECKER, user="agent")
        await sb.write_file(f"{workdir}/tests/test.sh", _LOCAL_VERIFY_WRAPPER, user="agent")
        await sb.exec(f"cd {workdir} && bash tests/test.sh", user="agent", timeout=timeout_sec, check=False)
        raw = await sb.read_file(f"{workdir}/reward.txt", user="agent")
        reward = float(raw.strip())
        if reward != reward or not (0.0 <= reward <= 1.0):  # NaN / out-of-range
            reward = 0.0
        return EvalResult(float(reward), True)
    except Exception:
        if ep_dir:
            try:
                os.makedirs(os.path.join(ep_dir, "verify"), exist_ok=True)
                with open(os.path.join(ep_dir, "verify", "reward_layer.err"), "a") as f:
                    f.write(f"--- {time.strftime('%Y-%m-%dT%H:%M:%S')} verify-side failure folded to 0.0 ---\n")
                    traceback.print_exc(file=f)
            except OSError:
                pass
        return EvalResult(0.0, True)


async def _grade_swebench(md: dict, diff_text: str, timeout_sec: int) -> EvalResult:
    """reward=1.0 iff sweb's get_eval_report declares the instance ``resolved``."""
    instance_id = md["instance_id"]
    inst = md["grading"]["sweb_instance"]

    if _SWEBENCH_IMPORT_ERROR is not None:
        logger.error(
            "[swe.swebench] %s: swebench import failed: %r; reward=0",
            instance_id,
            _SWEBENCH_IMPORT_ERROR,
        )
        return EvalResult(0.0, True)

    try:
        ts = _build_test_spec(inst)
        eval_sh = ts.eval_script  # may raise on unknown repo/version
    except Exception as e:
        logger.warning("[swe.swebench] %s: make_test_spec/eval_script failed: %s; reward=0", instance_id, e)
        return EvalResult(0.0, True)

    image = md["image"]
    if not image:
        logger.warning("[swe.swebench] %s: missing image; reward=0", instance_id)
        return EvalResult(0.0, True)

    async with E2BSandbox(image) as ev:
        await asyncio.gather(
            ev.write_file("/tmp/patch.diff", diff_text or "", user="root"),
            ev.write_file("/tmp/eval.sh", eval_sh, user="root"),
        )
        # Apply the model patch first (eval_script assumes it is already applied);
        # if no apply strategy works, the instance is unsolvable -- skip the eval.
        if not await _apply_model_patch(ev, md["workdir"]):
            logger.warning("[swe.swebench] %s: model patch failed to apply; reward=0", instance_id)
            return EvalResult(0.0, False)
        exit_code, log = await exec_and_wait(
            ev, cmd="bash /tmp/eval.sh", user="root", time_budget_sec=timeout_sec, tag="eval", want_output=True
        )

    try:
        report = _eval_report_from_log(ts, instance_id, diff_text, log)
    except Exception as e:
        logger.warning(
            "[swe.swebench] %s: get_eval_report failed: %s; reward=0 (tail=%r)",
            instance_id,
            e,
            log[-600:],
        )
        return EvalResult(0.0, True)

    info = report.get(instance_id, {})
    _log_swebench_result(instance_id, exit_code, info, log)
    return EvalResult(1.0 if info.get("resolved") else 0.0, bool(info.get("patch_successfully_applied")))

