import glob, json, os, torch

# 1. Inspect rollout_1.pt, rollout_5.pt, rollout_9.pt structure
for p in sorted(glob.glob("/workspace/observed_run/rollout_dumps/*.pt")):
    d = torch.load(p, map_location="cpu", weights_only=False)
    print(f"=== {os.path.basename(p)} ===")
    for i, s in enumerate(d["samples"]):
        if isinstance(s, dict):
            print(f"  [{i}] status={s.get('status')} reward={s.get('reward')} resp_len={s.get('response_length')} remove={s.get('remove_sample')} inst={(s.get('metadata') or {}).get('instance_id')} abort={(s.get('metadata') or {}).get('abort_reason')} exit={(s.get('metadata') or {}).get('agent_exit_code')}")
        else:
            print(f"  [{i}] type={type(s)} {s}")

# 2. Check all 72 episodes for trajectory.jsonl, reward.txt, patch.diff, sandbox.log, verify_*, etc.
ep_dirs = sorted(glob.glob("/workspace/observed_run/episodes/*"))
file_counts = {}
for d in ep_dirs:
    for root, dirs, files in os.walk(d):
        for fn in files:
            rel = os.path.relpath(os.path.join(root, fn), d)
            file_counts[rel] = file_counts.get(rel, 0) + 1
print("File counts across 72 episodes:", file_counts)
PY

